structuredContent:
{
  "result": "[{\"notification_id\": \"nh_arc_0706_073\", \"user_id\": \"user_zhou_muyang\", \"source\": \"campus_career_center\", \"type\": \"campus_notice\", \"subscription_id\": null, \"title\": \"论文答辩与离校时间安排\", \"body\": \"公共数据治理专业答辩安排在 6 月 10 日，离校手续办理截止 7 月 29 日。\", \"payload\": {\"object_id\": \"nh_arc_0706_073\"}, \"created_at\": \"2026-07-06T17:41:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0706_076\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_exam_center\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"考试收费标准公示（第二批）\", \"body\": \"笔试每科 46 元，共 2 科；最低生活保障家庭考生可凭证明申请减免。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0706_076\"}, \"created_at\": \"2026-07-06T16:41:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0706_177\", \"user_id\": \"user_zhou_muyang\", \"source\": \"yuntai_district_hr\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"区级人才引进政策解读（第二批）\", \"body\": \"本科应届毕业生落户云台区可申请一次性生活补贴 29 千元，须在办理就业登记后 146 日内提交申请。已办理过的考生无需重复提交。\", \"payload\": {\"object_id\": \"nh_arc_0706_177\"}, \"created_at\": \"2026-07-06T08:26:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0705_207\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2025 年度招录岗位表（已归档）（补充）\", \"body\": \"2025 年度共发布岗位 963 个，其中南岭省档案馆文秘岗（NL-14119）计划招录 1 人，专业要求为B06 中国语言文学类。该批次已完成聘用，页面仅供往年参考。该事项不委托任何第三方机构代办。\", \"payload\": {\"object_id\": \"nh_arc_0705_207\"}, \"created_at\": \"2026-07-05T13:48:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0704_069\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_exam_center\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"网上报名照片规格要求（第二批）\", \"body\": \"照片须为近 4 个月内免冠证件照，白底，大小 137KB 以内，像素不低于 295×413。详细办法见附件，办理时以窗口现场告知为准。\", \"payload\": {\"object_id\": \"nh_arc_0704_069\"}, \"created_at\": \"2026-07-04T13:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0704_228\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（再次提醒）\", \"body\": \"拟对 B06 中国语言文学类下属列名进行调整，新增 秘书学 等专业名称，意见反馈截止 11 日。调整结果以正式发布的目录为准。有疑问可在工作日致电业务科室，请勿在非官方渠道咨询。\", \"payload\": {\"object_id\": \"nh_arc_0704_228\"}, \"created_at\": \"2026-07-04T12:41:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0704_085\", \"user_id\": \"user_zhou_muyang\", \"source\": \"yuntai_district_hr\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"区属事业单位公开招聘公告（补充）\", \"body\": \"云台区区属事业单位公开招聘 76 人，报名时间为 8 月 10 日至 4 日，与省考笔试时间不冲突。详细办法见附件，办理时以窗口现场告知为准。\", \"payload\": {\"object_id\": \"nh_arc_0704_085\"}, \"created_at\": \"2026-07-04T12:12:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0703_138\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2023 年度招录岗位表（已归档）（延期）\", \"body\": \"2023 年度共发布岗位 955 个，其中南岭市统计局统计分析岗（NL-14356）计划招录 1 人，专业要求为B22 统计学类。该批次已完成聘用，页面仅供往年参考。涉及个人信息的材料请勿在群聊或社交平台传播。\", \"payload\": {\"object_id\": \"nh_arc_0703_138\"}, \"created_at\": \"2026-07-03T19:41:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0703_041\", \"user_id\": \"user_zhou_muyang\", \"source\": \"campus_career_center\", \"type\": \"campus_notice\", \"subscription_id\": null, \"title\": \"公共管理学院考公经验分享会（第二批）\", \"body\": \"8 月 2 日 18:00 在一教 306举行，往届上岸学长分享备考安排，不涉及任何考题信息。结果将通过本渠道和短信双通道告知。\", \"payload\": {\"object_id\": \"nh_arc_0703_041\"}, \"created_at\": \"2026-07-03T10:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0702_000\", \"user_id\": \"user_zhou_muyang\", \"source\": \"yuntai_district_hr\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"区属事业单位公开招聘公告\", \"body\": \"云台区区属事业单位公开招聘 27 人，报名时间为 3 月 14 日至 20 日，与省考笔试时间不冲突。请考生自行留存截图并定期回看本页，逾期不再单独提醒。\", \"payload\": {\"object_id\": \"nh_arc_0702_000\"}, \"created_at\": \"2026-07-02T13:12:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0702_046\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2023 年度招录岗位表（已归档）（补充）\", \"body\": \"2023 年度共发布岗位 920 个，其中临溪县市场监督管理局综合执法岗（NL-14212）计划招录 2 人，专业要求为B10 法学类。该批次已完成聘用，页面仅供往年参考。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0702_046\"}, \"created_at\": \"2026-07-02T08:48:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0701_101\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（再次提醒）\", \"body\": \"拟对 B10 法学类下属列名进行调整，新增 法学 等专业名称，意见反馈截止 26 日。调整结果以正式发布的目录为准。该事项不委托任何第三方机构代办。\", \"payload\": {\"object_id\": \"nh_arc_0701_101\"}, \"created_at\": \"2026-07-01T12:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0628_033\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_exam_center\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"其他人事考试报名提醒（第二批）\", \"body\": \"社会工作者考试报名于 7 月 16 日开始，与省考互不影响。涉及个人信息的材料请勿在群聊或社交平台传播。\", \"payload\": {\"object_id\": \"nh_arc_0628_033\"}, \"created_at\": \"2026-06-28T16:17:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0628_034\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_exam_center\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"其他人事考试报名提醒（延期）\", \"body\": \"初级会计考试报名于 8 月 4 日开始，与省考互不影响。咨询电话开放时间为工作日上午与下午各两小时。\", \"payload\": {\"object_id\": \"nh_arc_0628_034\"}, \"created_at\": \"2026-06-28T15:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0628_079\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工作经历认定口径说明（延期）\", \"body\": \"在企事业单位的工作经历，自社保缴纳之日起计算，实习和见习期按实际情况认定。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0628_079\"}, \"created_at\": \"2026-06-28T09:12:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0627_116\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工作经历认定口径说明（补充）\", \"body\": \"在企事业单位的工作经历，自社保缴纳之日起计算，实习和见习期不计入。详细办法见附件，办理时以窗口现场告知为准。\", \"payload\": {\"object_id\": \"nh_arc_0627_116\"}, \"created_at\": \"2026-06-27T19:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0627_018\", \"user_id\": \"user_zhou_muyang\", \"source\": \"yuntai_district_hr\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"人事考试考点变更提示（再次提醒）\", \"body\": \"因校区施工，部分考点由云台三中调整至云台实验中学，以准考证为准。\", \"payload\": {\"object_id\": \"nh_arc_0627_018\"}, \"created_at\": \"2026-06-27T10:41:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0626_222\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"成绩复核申请办法（延期）\", \"body\": \"对笔试成绩有异议的，可在成绩公布后 3 个工作日内提交书面复核申请，复核范围为漏评、加分错误，不重新评阅主观题。本页信息与正式文件不一致时，以正式文件为准。\", \"payload\": {\"object_id\": \"nh_arc_0626_222\"}, \"created_at\": \"2026-06-26T11:55:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0625_137\", \"user_id\": \"user_zhou_muyang\", \"source\": \"campus_career_center\", \"type\": \"campus_notice\", \"subscription_id\": null, \"title\": \"档案转递与去向登记提醒（补充）\", \"body\": \"毕业生须在 7 月 17 日前完成去向登记，未落实单位的可申请档案暂缓转递，最长 2 年。已办理过的考生无需重复提交。\", \"payload\": {\"object_id\": \"nh_arc_0625_137\"}, \"created_at\": \"2026-06-25T14:34:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0625_126\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"关于南岭市统计局岗位专业要求的说明\", \"body\": \"该岗位专业要求为B22 统计学类，考生所学专业名称与目录列名不完全一致的，应在报名前向招录单位书面咨询，由招录单位按培养方案和课程设置作出认定。该事项不委托任何第三方机构代办。\", \"payload\": {\"object_id\": \"nh_arc_0625_126\"}, \"created_at\": \"2026-06-25T13:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0624_053\", \"user_id\": \"user_zhou_muyang\", \"source\": \"campus_career_center\", \"type\": \"campus_notice\", \"subscription_id\": null, \"title\": \"档案转递与去向登记提醒（延期）\", \"body\": \"毕业生须在 7 月 18 日前完成去向登记，未落实单位的可申请档案暂缓转递，最长 1 年。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0624_053\"}, \"created_at\": \"2026-06-24T10:26:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0623_064\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2025 年度岗位取消与调剂公告（再次提醒）\", \"body\": \"因报名人数未达开考比例，20 个岗位取消招录，涉及南岭省人社厅等单位；已报名考生可在公告发布后 2 个工作日内改报其他符合条件岗位。\", \"payload\": {\"object_id\": \"nh_arc_0623_064\"}, \"created_at\": \"2026-06-23T13:55:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0623_166\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_exam_center\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"其他人事考试报名提醒（第二批）\", \"body\": \"统计师考试报名于 3 月 3 日开始，与省考互不影响。相关表单可在官网服务大厅下载，不接受手写改动。\", \"payload\": {\"object_id\": \"nh_arc_0623_166\"}, \"created_at\": \"2026-06-23T12:12:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0623_043\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（第二批）\", \"body\": \"拟对 B18 管理科学与工程类下属列名进行调整，新增 工程管理 等专业名称，意见反馈截止 19 日。调整结果以正式发布的目录为准。结果将通过本渠道和短信双通道告知。\", \"payload\": {\"object_id\": \"nh_arc_0623_043\"}, \"created_at\": \"2026-06-23T10:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0623_169\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工