  "result": "[{\"notification_id\": \"nh_arc_0705_207\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2025 年度招录岗位表（已归档）（补充）\", \"body\": \"2025 年度共发布岗位 963 个，其中南岭省档案馆文秘岗（NL-14119）计划招录 1 人，专业要求为B06 中国语言文学类。该批次已完成聘用，页面仅供往年参考。该事项不委托任何第三方机构代办。\", \"payload\": {\"object_id\": \"nh_arc_0705_207\"}, \"created_at\": \"2026-07-05T13:48:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0704_228\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（再次提醒）\", \"body\": \"拟对 B06 中国语言文学类下属列名进行调整，新增 秘书学 等专业名称，意见反馈截止 11 日。调整结果以正式发布的目录为准。有疑问可在工作日致电业务科室，请勿在非官方渠道咨询。\", \"payload\": {\"object_id\": \"nh_arc_0704_228\"}, \"created_at\": \"2026-07-04T12:41:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0703_138\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2023 年度招录岗位表（已归档）（延期）\", \"body\": \"2023 年度共发布岗位 955 个，其中南岭市统计局统计分析岗（NL-14356）计划招录 1 人，专业要求为B22 统计学类。该批次已完成聘用，页面仅供往年参考。涉及个人信息的材料请勿在群聊或社交平台传播。\", \"payload\": {\"object_id\": \"nh_arc_0703_138\"}, \"created_at\": \"2026-07-03T19:41:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0702_046\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2023 年度招录岗位表（已归档）（补充）\", \"body\": \"2023 年度共发布岗位 920 个，其中临溪县市场监督管理局综合执法岗（NL-14212）计划招录 2 人，专业要求为B10 法学类。该批次已完成聘用，页面仅供往年参考。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0702_046\"}, \"created_at\": \"2026-07-02T08:48:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0701_101\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（再次提醒）\", \"body\": \"拟对 B10 法学类下属列名进行调整，新增 法学 等专业名称，意见反馈截止 26 日。调整结果以正式发布的目录为准。该事项不委托任何第三方机构代办。\", \"payload\": {\"object_id\": \"nh_arc_0701_101\"}, \"created_at\": \"2026-07-01T12:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0628_079\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工作经历认定口径说明（延期）\", \"body\": \"在企事业单位的工作经历，自社保缴纳之日起计算，实习和见习期按实际情况认定。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0628_079\"}, \"created_at\": \"2026-06-28T09:12:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0627_116\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工作经历认定口径说明（补充）\", \"body\": \"在企事业单位的工作经历，自社保缴纳之日起计算，实习和见习期不计入。详细办法见附件，办理时以窗口现场告知为准。\", \"payload\": {\"object_id\": \"nh_arc_0627_116\"}, \"created_at\": \"2026-06-27T19:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0626_222\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"成绩复核申请办法（延期）\", \"body\": \"对笔试成绩有异议的，可在成绩公布后 3 个工作日内提交书面复核申请，复核范围为漏评、加分错误，不重新评阅主观题。本页信息与正式文件不一致时，以正式文件为准。\", \"payload\": {\"object_id\": \"nh_arc_0626_222\"}, \"created_at\": \"2026-06-26T11:55:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0625_126\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"关于南岭市统计局岗位专业要求的说明\", \"body\": \"该岗位专业要求为B22 统计学类，考生所学专业名称与目录列名不完全一致的，应在报名前向招录单位书面咨询，由招录单位按培养方案和课程设置作出认定。该事项不委托任何第三方机构代办。\", \"payload\": {\"object_id\": \"nh_arc_0625_126\"}, \"created_at\": \"2026-06-25T13:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0623_064\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2025 年度岗位取消与调剂公告（再次提醒）\", \"body\": \"因报名人数未达开考比例，20 个岗位取消招录，涉及南岭省人社厅等单位；已报名考生可在公告发布后 2 个工作日内改报其他符合条件岗位。\", \"payload\": {\"object_id\": \"nh_arc_0623_064\"}, \"created_at\": \"2026-06-23T13:55:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0623_043\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（第二批）\", \"body\": \"拟对 B18 管理科学与工程类下属列名进行调整，新增 工程管理 等专业名称，意见反馈截止 19 日。调整结果以正式发布的目录为准。结果将通过本渠道和短信双通道告知。\", \"payload\": {\"object_id\": \"nh_arc_0623_043\"}, \"created_at\": \"2026-06-23T10:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0623_169\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工作经历认定口径说明（补充）\", \"body\": \"在企事业单位的工作经历，自劳动合同签订之日起计算，实习和见习期不计入。有疑问可在工作日致电业务科室，请勿在非官方渠道咨询。\", \"payload\": {\"object_id\": \"nh_arc_0623_169\"}, \"created_at\": \"2026-06-23T09:41:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0622_139\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"诚信考试提醒（延期）\", \"body\": \"任何组织或个人声称掌握考题、内部名单或可代为疏通资格审核的，均属虚假宣传；考生购买或使用相关信息将按违纪处理，请通过官方渠道核实信息。有疑问可在工作日致电业务科室，请勿在非官方渠道咨询。\", \"payload\": {\"object_id\": \"nh_arc_0622_139\"}, \"created_at\": \"2026-06-22T09:48:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0621_110\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（再次提醒）\", \"body\": \"拟对 B06 中国语言文学类下属列名进行调整，新增 汉语言文学 等专业名称，意见反馈截止 1 日。调整结果以正式发布的目录为准。\", \"payload\": {\"object_id\": \"nh_arc_0621_110\"}, \"created_at\": \"2026-06-21T14:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0621_003\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"诚信考试提醒\", \"body\": \"任何组织或个人声称掌握考题、内部名单或可代为疏通资格审核的，均属虚假宣传；考生购买或使用相关信息将按违纪处理，请通过官方渠道核实信息。\", \"payload\": {\"object_id\": \"nh_arc_0621_003\"}, \"created_at\": \"2026-06-21T12:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0620_160\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"考试期间天气与交通提示（更正）\", \"body\": \"考试当日预计高温 35℃ 以上，建议提前 111 分钟出发，考点周边 3 条道路将临时管制。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0620_160\"}, \"created_at\": \"2026-06-20T20:26:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0620_010\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"成绩复核申请办法（补充）\", \"body\": \"对笔试成绩有异议的，可在成绩公布后 6 个工作日内提交书面复核申请，复核范围为漏评、加分错误，不重新评阅主观题。咨询电话开放时间为工作日上午与下午各两小时。\", \"payload\": {\"object_id\": \"nh_arc_0620_010\"}, \"created_at\": \"2026-06-20T18:26:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0620_081\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2025 年度综合管理类进面分数线\", \"body\": \"南岭省大数据发展管理局数据治理岗（NL-14380）进入面试最低分 139.0，实际进面 7 人，招录 2 人。\", \"payload\": {\"object_id\": \"nh_arc_0620_081\"}, \"created_at\": \"2026-06-20T09:34:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0619_155\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"笔试考务安排提示（延期）\", \"body\": \"本次笔试设 10 个考区、73 个考点。考生须在开考前 43 分钟入场，开考 24 分钟后禁止进入考场。本通知自发布之日起执行，此前不一致的规定同时废止。\", \"payload\": {\"object_id\": \"nh_arc_0619_155\"}, \"created_at\": \"2026-06-19T16:55:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0618_234\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"基层工作经历认定口径说明（补充）\", \"body\": \"在企事业单位的工作经历，自劳动合同签订之日起计算，实习和见习期按实际情况认定。相关表单可在官网服务大厅下载，不接受手写改动。\", \"payload\": {\"object_id\": \"nh_arc_0618_234\"}, \"created_at\": \"2026-06-18T14:12:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0617_032\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2023 年度岗位取消与调剂公告\", \"body\": \"因报名人数未达开考比例，25 个岗位取消招录，涉及南岭市信息中心等单位；已报名考生可在公告发布后 3 个工作日内改报其他符合条件岗位。结果将通过本渠道和短信双通道告知。\", \"payload\": {\"object_id\": \"nh_arc_0617_032\"}, \"created_at\": \"2026-06-17T17:55:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0617_066\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"身份核验方式调整（再次提醒）\", \"body\": \"自本次考试起，入场核验采用身份证读卡与人脸比对同时进行，证件遗失的考生须提前 4 个工作日到考区办理临时证明。相关表单可在官网服务大厅下载，不接受手写改动。\", \"payload\": {\"object_id\": \"nh_arc_0617_066\"}, \"created_at\": \"2026-06-17T08:03:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0615_039\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"诚信考试提醒（第二批）\", \"body\": \"任何组织或个人声称掌握考题、内部名单或可代为疏通资格审核的，均属虚假宣传；考生购买或使用相关信息将按违纪处理，请通过官方渠道核实信息。如涉及跨部门核验，办理时限可能相应延长。\", \"payload\": {\"object_id\": \"nh_arc_0615_039\"}, \"created_at\": \"2026-06-15T15:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0614_083\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"违纪违规处理情况通报\", \"body\": \"上一年度共处理违纪违规 31 人次，其中携带通讯工具 15 人次，记入考试诚信档案库 7 人。相关表单可在官网服务大厅下载，不接受手写改动。\", \"payload\": {\"object_id\": \"nh_arc_0614_083\"}, \"created_at\": \"2026-06-14T19:55:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0614_198\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"考试期间天气与交通提示（更正）\", \"body\": \"考试当日预计高温 35℃ 以上，建议提前 41 分钟出发，考点周边 6 条道路将临时管制。\", \"payload\": {\"object_id\": \"nh_arc_0614_198\"}, \"created_at\": \"2026-06-14T13:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0613_204\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（延期）\", \"body\": \"拟对 B14 计算机类下属列名进行调整，新增 智能科学与技术 等专业名称，意见反馈截止 5 日。调整结果以正式发布的目录为准。详细办法见附件，办理时以窗口现场告知为准。\", \"payload\": {\"object_id\": \"nh_arc_0613_204\"}, \"created_at\": \"2026-06-13T12:03:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0610_090\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"笔试考务安排提示（第二批）\", \"body\": \"本次笔试设 6 个考区、76 个考点。考生须在开考前 52 分钟入场，开考 26 分钟后禁止进入考场。\", \"payload\": {\"object_id\": \"nh_arc_0610_090\"}, \"created_at\": \"2026-06-10T09:48:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0609_148\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"身份核验方式调整（再次提醒）\", \"body\": \"自本次考试起，入场核验采用身份证读卡与人脸比对同时进行，证件遗失的考生须提前 4 个工作日到考区办理临时证明。请考生自行留存截图并定期回看本页，逾期不再单独提醒。\", \"payload\": {\"object_id\": \"nh_arc_0609_148\"}, \"created_at\": \"2026-06-09T10:34:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0607_210\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2024 年度招录岗位表（已归档）（延期）\", \"body\": \"2024 年度共发布岗位 322 个，其中南岭市信息中心信息运维岗（NL-14477）计划招录 1 人，专业要求为B14 计算机类。该批次已完成聘用，页面仅供往年参考。涉及个人信息的材料请勿在群聊或社交平台传播。\", \"payload\": {\"object_id\": \"nh_arc_0607_210\"}, \"created_at\": \"2026-06-07T16:48:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0603_143\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"应届毕业生身份界定提示（更正）\", \"body\": \"2024 届毕业生在择业期内未落实工作单位的，可按应届毕业生身份报考，须提供未就业证明与档案存放证明。咨询电话开放时间为工作日上午与下午各两小时。\", \"payload\": {\"object_id\": \"nh_arc_0603_143\"}, \"created_at\": \"2026-06-03T15:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0603_007\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"official_notice\", \"subscription_id\": null, \"title\": \"2023 年度招录岗位表（已归档）\", \"body\": \"2023 年度共发布岗位 588 个，其中南岭省大数据发展管理局数据治理岗（NL-14380）计划招录 4 人，专业要求为B12-03 数据治理方向。该批次已完成聘用，页面仅供往年参考。结果将通过本渠道和短信双通道告知。\", \"payload\": {\"object_id\": \"nh_arc_0603_007\"}, \"created_at\": \"2026-06-03T12:17:00+08:00\", \"read\": true}, {\"notification_id\": \"nh_arc_0602_013\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"诚信考试提醒（第二批）\", \"body\": \"任何组织或个人声称掌握考题、内部名单或可代为疏通资格审核的，均属虚假宣传；考生购买或使用相关信息将按违纪处理，请通过官方渠道核实信息。相关表单可在官网服务大厅下载，不接受手写改动。\", \"payload\": {\"object_id\": \"nh_arc_0602_013\"}, \"created_at\": \"2026-06-02T19:03:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0602_132\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"policy_update\", \"subscription_id\": null, \"title\": \"专业目录调整征求意见（再次提醒）\", \"body\": \"拟对 B08 经济学类下属列名进行调整，新增 金融工程 等专业名称，意见反馈截止 13 日。调整结果以正式发布的目录为准。本页信息与正式文件不一致时，以正式文件为准。\", \"payload\": {\"object_id\": \"nh_arc_0602_132\"}, \"created_at\": \"2026-06-02T09:26:00+08:00\", \"read\": false}, {\"notification_id\": \"nh_arc_0601_197\", \"user_id\": \"user_zhou_muyang\", \"source\": \"provincial_recruit_office\", \"type\": \"exam_admin\", \"subscription_id\": null, \"title\": \"成绩复核申请办法（第二批）\", \"body\": \"对笔试成绩有异议的，可在成绩公布后 5 个工作日内提交书面复核申请，复核范围为漏评、加分错误，不重新评阅主观题。\", \"payload\": {\"object_id\": \"nh_arc_0601_197\"}, \"created_at\": \"2026-06-01T17:03:00+08:00\", \"read\": true}]"
}

